    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();

        if (n > m) {
            int temp = n;
            n = m;
            m = temp;
        }

        int size = 1 << n;
        int[][] dp = new int[size][size];
        for (int[] row : dp) {
            Arrays.fill(row, 1000000000);
        }
        Arrays.fill(dp[0], 0);

        for (int step = 0; step < m; step++) {
            int[][] nextDp = new int[size][size];
            for (int[] row : nextDp) {
                Arrays.fill(row, 1000000000);
            }
            for (int prevMask = 0; prevMask < size; prevMask++) {
                for (int currMask = 0; currMask < size; currMask++) {
                    if (dp[prevMask][currMask] != 1000000000) {
                        int limit = (step == m - 1) ? 1 : size;
                        for (int nextMask = 0; nextMask < limit; nextMask++) {
                            int covered = 0;
                            for (int i = 0; i < n; i++) {
                                if (((1 << i) & currMask) == 0) {
                                    int up = i - 1;
                                    int down = i + 1;
                                    if (up >= 0 && ((1 << up) & currMask) != 0)
                                        covered |= 1 << i;
                                    if (down < n && ((1 << down) & currMask) != 0)
