                                    if (((1 << i) & prevMask) != 0)
                                        covered |= 1 << i;
                                    if (((1 << i) & nextMask) != 0)
                                        covered |= 1 << i;
                                }
                            }
                            int newCost = dp[prevMask][currMask] + n - Integer.bitCount(covered);
