                            }
                        }
                    }
                }
            }
            dp = nextDp;
        }

        int minResult = 1000000000;
        for (int[] row : dp) {
            for (int val : row) {
                if (val < minResult) {
                    minResult = val;
                }
            }
        }
        System.out.println(n * m - minResult);
    }
