import sys

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])

    if n > m:
        n, m = m, n

    size = 1 << n
    INF = 10**9
    dp = [[INF] * size for _ in range(size)]
    for row in dp:
        row[0] = 0

    for step in range(m):
        next_dp = [[INF] * size for _ in range(size)]
        for prev_mask in range(size):
            for curr_mask in range(size):
                if dp[prev_mask][curr_mask] != INF:
                    limit = 1 if step == m - 1 else size
                    for next_mask in range(limit):
                        covered = 0
                        for i in range(n):
                            if ((1 << i) & curr_mask) == 0:
                                up = i - 1
                                down = i + 1
                                if up >= 0 and ((1 << up) & curr_mask) != 0:
                                    covered |= 1 << i
                                if down < n and ((1 << down) & curr_mask) != 0:
                                    covered |= 1 << i
                                if ((1 << i) & prev_mask) != 0:
                                    covered |= 1 << i
                                if ((1 << i) & next_mask) != 0:
                                    covered |= 1 << i
                        new_cost = dp[prev_mask][curr_mask] + n - bin(covered).count('1')
                        if new_cost < next_dp[prev_mask][next_mask]:
                            next_dp[prev_mask][next_mask] = new_cost
        dp = next_dp

    min_result = INF
    for row in dp:
        for val in row:
            if val < min_result:
                min_result = val
    print(n * m - min_result)

